<?php require 'config.php';auth();$p=db();if($_SERVER['REQUEST_METHOD']==='POST'){check_token();$id=(int)($_POST['id']??0);$action=$_POST['action']??'';try{if($action==='delete'){$s=$p->prepare('DELETE FROM clients WHERE id=?');$s->execute([$id]);flash('Client deleted.');}else{$v=[trim($_POST['name']??''),trim($_POST['company']??''),trim($_POST['email']??''),trim($_POST['phone']??''),trim($_POST['notes']??'')];if(!$v[0]||!filter_var($v[2],FILTER_VALIDATE_EMAIL))throw new RuntimeException('Name and a valid email are required.');if($id){$s=$p->prepare('UPDATE clients SET name=?,company=?,email=?,phone=?,notes=? WHERE id=?');$s->execute([...$v,$id]);flash('Client updated.');}else{$s=$p->prepare('INSERT INTO clients(name,company,email,phone,notes) VALUES(?,?,?,?,?)');$s->execute($v);flash('Client added.');}}}catch(Throwable $e){flash($e instanceof RuntimeException?$e->getMessage():'Cannot delete client while projects are linked to it.','error');}header('Location: clients.php');exit;}$edit=null;if(isset($_GET['edit'])){$s=$p->prepare('SELECT * FROM clients WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$q='%'.trim($_GET['q']??'').'%';$s=$p->prepare('SELECT c.*,(SELECT COUNT(*) FROM projects WHERE client_id=c.id) pc FROM clients c WHERE c.name LIKE ? OR c.company LIKE ? OR c.email LIKE ? ORDER BY c.created_at DESC');$s->execute([$q,$q,$q]);$rows=$s->fetchAll();$page='Clients';require 'includes/header.php';?><div class="heading"><div><p class="eyebrow">RELATIONSHIP MANAGEMENT</p><h1>Clients</h1><p class="muted">Create, search, update, and manage client records.</p></div></div><section class="panel form-panel"><div class="panel-head"><div><h2><?=$edit?'Edit client':'Add a client'?></h2><p>Name and email are required.</p></div></div><form class="form-grid" method="post"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><input type="hidden" name="action" value="save"><label>Name *<input name="name" required value="<?=e($edit['name']??'')?>"></label><label>Company<input name="company" value="<?=e($edit['company']??'')?>"></label><label>Email *<input type="email" name="email" required value="<?=e($edit['email']??'')?>"></label><label>Phone<input name="phone" value="<?=e($edit['phone']??'')?>"></label><label class="wide">Notes<textarea name="notes" rows="2"><?=e($edit['notes']??'')?></textarea></label><div class="wide form-actions"><button class="btn primary"><?=$edit?'Save changes':'Add client'?></button><?php if($edit):?><a class="btn" href="clients.php">Cancel</a><?php endif;?></div></form></section><section class="panel listing"><div class="panel-head"><div><h2>Client directory <small><?=count($rows)?></small></h2></div><form class="search" method="get"><input name="q" placeholder="Search clients..." value="<?=e($_GET['q']??'')?>"><button class="btn">Search</button></form></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Company</th><th>Email / Phone</th><th>Projects</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['company']?:'—')?></td><td><?=e($r['email'])?><small><?=e($r['phone'])?></small></td><td><?=$r['pc']?></td><td class="actions"><a href="?edit=<?=$r['id']?>">Edit</a><form method="post" onsubmit="return confirm('Delete this client?')"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="action" value="delete"><button class="danger">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div></section><?php require 'includes/footer.php';?>
